const $=s=>document.querySelector(s);let songs=[],media={},filter='all',collection=location.hash==='#explorers'?'explorers':'little',current=null,favs=[];try{favs=JSON.parse(localStorage.getItem('lucas-song-favourites')||'[]');if(!Array.isArray(favs))favs=[]}catch{}function save(){try{localStorage.setItem('lucas-song-favourites',JSON.stringify(favs))}catch{}}function selection(){return songs.filter(s=>(s.collection||'little')===collection).filter(s=>filter==='all'||s.category===filter||(filter==='favourites'&&favs.includes(s.id)))}function render(){let group=songs.filter(s=>(s.collection||'little')===collection);const names={'Vehicles':'🚒 Trucks','Animals & nature':'🐙 Animals','Move & explore':'👐 Move','Everyday words':'🙂 My day','Rhythm & rhyme':'🎵 Rhymes','Stories & adventure':'🛶 Adventures','Words & numbers':'🔤 Words & numbers','Science & world':'🌍 Discover','Music & singing':'🎶 Music'};let topics=[['all','🌈 All songs'],...Array.from(new Set(group.map(s=>s.category))).map(c=>[c,names[c]||c]),['favourites','⭐ Favourites']];$('#topics').replaceChildren(...topics.map(([id,label])=>{let b=document.createElement('button');b.dataset.filter=id;b.textContent=label;b.setAttribute('aria-pressed',String(filter===id));return b}));document.querySelectorAll('[data-collection]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.collection===collection)));$('#collection-note').textContent=collection==='little'?'Familiar favourites and first adventures':'New stories, big ideas and songs to grow into';let list=selection();$('#tiles').replaceChildren(...list.map(s=>{let b=document.createElement('button');b.className='tile';b.setAttribute('aria-label','Play '+s.title);let picture=document.createElement('span');picture.className='picture';if(media[s.id]?.poster){let img=document.createElement('img');img.src=media[s.id].poster;img.alt='';img.loading='lazy';picture.append(img)}else{let e=document.createElement('span');e.className='emoji';e.textContent=s.emoji;picture.append(e)}let play=document.createElement('span');play.className='play';play.textContent='▶';picture.append(play);let label=document.createElement('span');label.className='label';let emoji=document.createElement('span');emoji.className='tiny';emoji.textContent=s.emoji;let name=document.createElement('span');name.textContent=s.childTitle;label.append(emoji,name);if(favs.includes(s.id)){let star=document.createElement('span');star.className='saved';star.textContent='★';label.append(star)}b.append(picture,label);b.onclick=()=>openSong(s);return b}));$('#status').textContent=list.length?'':'Tap the star on a song to save it here.';document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)))}function stop(){$('#screen').querySelector('video')?.pause();$('#screen').replaceChildren()}function setStar(){let active=favs.includes(current.id);$('#star').textContent=active?'★':'☆';$('#star').setAttribute('aria-pressed',String(active));$('#star').setAttribute('aria-label',active?'Remove favourite':'Save favourite')}function online(s){let f=document.createElement('iframe');f.src=`https://www.youtube-nocookie.com/embed/${s.videoId}?autoplay=1&rel=0&playsinline=1`;f.title=s.title;f.allow='autoplay; encrypted-media; fullscreen; picture-in-picture';f.allowFullscreen=true;$('#screen').append(f);$('#player-status').textContent='';}function openSong(s){stop();current=s;$('#shelf').hidden=true;$('#player').hidden=false;$('#playing-title').textContent=s.emoji+' '+s.childTitle;setStar();$('#player-status').textContent='';$('#toggle').hidden=!media[s.id]?.src;if(media[s.id]?.src){let v=document.createElement('video');v.src=media[s.id].src;v.controls=true;v.playsInline=true;v.preload='metadata';if(media[s.id].poster)v.poster=media[s.id].poster;v.setAttribute('aria-label',s.title);v.onplay=()=>{$('#toggle').textContent='Ⅱ Pause'};v.onpause=()=>{$('#toggle').textContent='▶ Play'};v.onended=()=>{$('#player-status').textContent='Sing it again, or choose another song.'};v.onerror=()=>{$('#player-status').textContent='This song could not load. Try Again or choose another song.'};$('#screen').append(v);v.play().catch(()=>{$('#player-status').textContent='Tap ▶ to start.'})}else online(s);$('#playing-title').focus();window.scrollTo(0,0)}$('#topics').addEventListener('click',e=>{let b=e.target.closest('[data-filter]');if(b){filter=b.dataset.filter;render()}});document.querySelectorAll('[data-collection]').forEach(b=>b.onclick=()=>{collection=b.dataset.collection;history.replaceState(null,'',collection==='explorers'?'#explorers':location.pathname+location.search);filter='all';render()});$('#back').onclick=async()=>{if(document.fullscreenElement)await document.exitFullscreen().catch(()=>{});stop();$('#player').hidden=true;$('#shelf').hidden=false;render();$('#tiles button')?.focus()};$('#star').onclick=()=>{if(!current)return;favs=favs.includes(current.id)?favs.filter(id=>id!==current.id):[...favs,current.id];save();setStar()};$('#toggle').onclick=()=>{let v=$('#screen video');if(!v)return;if(v.paused)v.play().catch(()=>{$('#player-status').textContent='Tap ▶ in the video to start.'});else v.pause()};$('#again').onclick=()=>{if(current)openSong(current)};$('#next').onclick=()=>{let list=selection();if(!list.length)list=songs.filter(s=>(s.collection||'little')===collection);let i=list.findIndex(s=>s.id===current?.id);openSong(list[(i+1)%list.length])};$('#fullscreen').onclick=()=>{let el=$('#screen'),v=el.querySelector('video');if(el.requestFullscreen)el.requestFullscreen().catch(()=>{$('#player-status').textContent='Use the player’s full-screen button.'});else if(v?.webkitEnterFullscreen)v.webkitEnterFullscreen()};Promise.all([fetch('songs.json').then(r=>{if(!r.ok)throw Error('songs');return r.json()}),fetch('local-media.json',{cache:'no-store'}).then(r=>r.ok?r.json():{}).catch(()=>({}))]).then(([s,m])=>{songs=s;media=m;render()}).catch(()=>{$('#status').textContent='The songs could not load. Please reload.'});
